DROP TABLE IF EXISTS `pagamento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pagamento` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `valorMensalidade` decimal(10,0) NOT NULL,
  `dataPagamento` datetime DEFAULT NULL,
  `dataVencimento` datetime DEFAULT NULL,
  `statusMensalidade` enum('P','E','A') NOT NULL COMMENT 'P : Pago\nE: Pendente\nA: Atraso',
  `idRestaurante` int unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_pagamento_Restaurante1_idx` (`idRestaurante`),
  CONSTRAINT `fk_pagamento_Restaurante1` FOREIGN KEY (`idRestaurante`) REFERENCES `restaurante` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
